L19_1.m_Pos = "C"
L19_1.m_Talk_KOREA = "이면세계를 무작위로 다이브하며, 스스로 이터니움을 확보 및 가공하는 팩토리 쉽."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "裏世界をランダムにダイブし、自らエタニウムを確保・加工するファクトリーシップ。"
L19_1.m_Talk_ENG = "A Factory Ship that dives the Counterside at random and secures and refines Eternium on its own."
L19_1.m_Talk_TWN = "能任意潛入異世界，自主取得並加工永恆之金的工廠艦。"
L19_1.m_Talk_DEU = "A Factory Ship that dives the Counterside at random and secures and refines Eternium on its own."
L19_1.m_Talk_FRA = "A Factory Ship that dives the Counterside at random and secures and refines Eternium on its own."
L20_1 = {}
