L20_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "더 나은 세상을 위해, 그건 반드시 필요한 일이었을 거예요."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "より良い世界のために、それは必要不可欠なことだったのでしょう。"
L20_1.m_Talk_ENG = "For a better world, it was something we absolutely needed."
