L21_1.m_Face = "UNIT_IDLE"
L21_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L21_1.m_Pos = "C"
L21_1.m_Talk_KOREA = "하지만 알파트릭스라고 해도, 느닷없이 그런 엄청난 함선을 제작할 기술력은 없었죠."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "ただ、いくらアルファトリックスといえ、突然そんな艦船を作る技術力は持っていなかった。"
L21_1.m_Talk_ENG = "But even Alphatrix didn't have the tech to suddenly build a ship of that scale."
