L29_1 = {}
L29_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@19#Talk"
L29_1.m_CutScenProcessKey = 0
L29_1.m_CutScenID = 7800102
L29_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_IDLE"
L29_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L29_1.m_Pos = "C"
L29_1.m_Talk_KOREA = "허수 공간에서 일부러 통신 채널을 개방했던 건, 내 본체의 위치를 역추적하기 위함이었나?"
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "虚数空間でわざわざ通信チャンネルを開放したのは、私の本体を逆追跡するためだったのか？"
L29_1.m_Talk_ENG = "You deliberately opened a comms channel in the imaginary space to back-trace the location of my core body."
L29_1.m_Talk_TWN = "故意在量子空間開放通訊頻道，是為了反追蹤我本體的位置嗎？"
L29_1.m_Talk_DEU = "You deliberately opened a comms channel in the imaginary space to back-trace the location of my core body."
L29_1.m_Talk_FRA = "You deliberately opened a comms channel in the imaginary space to back-trace the location of my core body."
L30_1 = {}
L30_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@20#Talk"
L30_1.m_CutScenProcessKey = 0
L30_1.m_CutScenID = 7800102
L30_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_IDLE"
L30_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L30_1.m_Pos = "C"
L30_1.m_Talk_KOREA = "여기까지 계산해 두다니, 역시 빈틈이 없군. 알파트릭스 회장이 남긴 괴물다워."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "ここまで計算するとは隙がないな。さすがアルファトリックス会長が残した化け物だ。"
L30_1.m_Talk_ENG = "To have calculated this far... no loose ends indeed. Fitting for the monster Alphatrix's late President left behind."
L30_1.m_Talk_TWN = "能預先算到這一步，果然無懈可擊。不愧是阿爾法崔克斯會長留下的怪物。"
L30_1.m_Talk_DEU = "To have calculated this far... no loose ends indeed. Fitting for the monster Alphatrix's late President left behind."
L30_1.m_Talk_FRA = "To have calculated this far... no loose ends indeed. Fitting for the monster Alphatrix's late President left behind."
