L32_1 = {}
L32_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@21#Talk"
L32_1.m_CutScenProcessKey = 0
L32_1.m_CutScenID = 7800102
L32_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_PRIDE"
L32_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L32_1.m_Pos = "C"
L32_1.m_Talk_KOREA = "저는 이미 그룹의 회장직을 계승했답니다."
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "私はすでに会長職を継承していますよ。"
L32_1.m_Talk_ENG = "I have already inherited that position."
L32_1.m_Talk_TWN = "我已經繼承了集團的會長職位。"
L32_1.m_Talk_DEU = "I have already inherited that position."
L32_1.m_Talk_FRA = "I have already inherited that position."
L33_1 = {}
L33_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@22#Talk"
L33_1.m_CutScenProcessKey = 0
L33_1.m_CutScenID = 7800102
L33_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_LAUGH"
L33_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L33_1.m_Pos = "C"
L33_1.m_Talk_KOREA = "후후, 그래도 괴물이라 불리는 건, 역시 서운하네요."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "ふふ……でも化け物だと呼ばれるのは、やはり悲しいですね。"
L33_1.m_Talk_ENG = "Haha, still, being called a \"monster\" does sting a little."
L33_1.m_Talk_TWN = "呵呵，但被稱作怪物，還是有點委屈呢。"
L33_1.m_Talk_DEU = "Haha, still, being called a \"monster\" does sting a little."
L33_1.m_Talk_FRA = "Haha, still, being called a \"monster\" does sting a little."
