L35_1 = {}
L35_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@23#Talk"
L35_1.m_CutScenProcessKey = 0
L35_1.m_CutScenID = 7800102
L35_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_IDLE"
L35_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L35_1.m_Pos = "C"
L35_1.m_Talk_KOREA = "아무것도 느끼지 못하는 주제에, 인간인 척 행세하는 건가?"
L35_1.m_fTalkTime = 0.03
L35_1.m_Talk_JPN = "何も感じない作り物の器で、人間ぶるつもりか？"
L35_1.m_Talk_ENG = "You feel nothing, yet you pretend to be human?"
L35_1.m_Talk_TWN = "你明明什麼都感覺不到，現在是在扮演人類嗎？"
L35_1.m_Talk_DEU = "You feel nothing, yet you pretend to be human?"
L35_1.m_Talk_FRA = "You feel nothing, yet you pretend to be human?"
