L37_1 = {}
L37_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@24#Talk"
L37_1.m_CutScenProcessKey = 0
L37_1.m_CutScenID = 7800102
L37_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_PRIDE"
L37_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L37_1.m_Pos = "C"
L37_1.m_Talk_KOREA = "네, 왜냐하면 저는 인간이니까요."
L37_1.m_fTalkTime = 0.03
L37_1.m_Talk_JPN = "はい、なぜなら私は人間ですから。"
L37_1.m_Talk_ENG = "Yes, because I am human."
L37_1.m_Talk_TWN = "對，因為我本來就是人類。"
L37_1.m_Talk_DEU = "Yes, because I am human."
L37_1.m_Talk_FRA = "Yes, because I am human."
L38_1 = {}
L38_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@25#Talk"
L38_1.m_CutScenProcessKey = 0
L38_1.m_CutScenID = 7800102
L38_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_LAUGH"
L38_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L38_1.m_Pos = "C"
L38_1.m_Talk_KOREA = "그리고 그건 당신도 마찬가지라고 생각해요, 엠버 박사님."
L38_1.m_fTalkTime = 0.03
L38_1.m_Talk_JPN = "それはあなたも同じだと思いますよ、アンバー博士。"
L38_1.m_Talk_ENG = "And I think that applies to you as well, Dr. Ember."
L38_1.m_Talk_TWN = "而且我認為這點妳也一樣，琥珀博士。"
L38_1.m_Talk_DEU = "And I think that applies to you as well, Dr. Ember."
L38_1.m_Talk_FRA = "And I think that applies to you as well, Dr. Ember."
