L40_1 = {}
L40_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@26#Talk"
L40_1.m_CutScenProcessKey = 0
L40_1.m_CutScenID = 7800102
L40_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_IDLE"
L40_1.m_StartFXSoundName = "FX_COMBAT_ALL_MECHANIC_WORK_28"
L40_1.m_CharStrID = "EVOLVE_SCAVENGER_NULL_NULL"
L40_1.m_Pos = "C"
L40_1.m_Talk_KOREA = "착각하지 마라. 인간 시절의 나약한 육체와 이름은 이미 버린 지 오래다."
L40_1.m_fTalkTime = 0.03
L40_1.m_Talk_JPN = "思い違いにも甚だしい。人間だった頃の脆弱な肉体と名前はとうに捨てた。"
L40_1.m_Talk_ENG = "Do not delude yourself. I discarded that frail human body and name long ago."
L40_1.m_Talk_TWN = "妳別誤會了。我早就放棄人類時期那軟弱的軀體與名字。"
L40_1.m_Talk_DEU = "Do not delude yourself. I discarded that frail human body and name long ago."
L40_1.m_Talk_FRA = "Do not delude yourself. I discarded that frail human body and name long ago."
