L42_1 = {}
L42_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@27#Talk"
L42_1.m_CutScenProcessKey = 0
L42_1.m_CutScenID = 7800102
L42_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_SERIOUS"
L42_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L42_1.m_Pos = "C"
L42_1.m_Talk_KOREA = "하지만 인간은 실패로부터 깨닫고, 현실을 바꿀 힘을 가지고 있는 걸요."
L42_1.m_fTalkTime = 0.03
L42_1.m_Talk_JPN = "でも人間は失敗から学び、現実を変える力を持っています。"
L42_1.m_Talk_ENG = "Yet humans learn from failure and have the power to change reality."
L42_1.m_Talk_TWN = "但人類會從失敗中領悟，進而擁有改變現實的力量。"
L42_1.m_Talk_DEU = "Yet humans learn from failure and have the power to change reality."
L42_1.m_Talk_FRA = "Yet humans learn from failure and have the power to change reality."
L43_1 = {}
L43_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@28#Talk"
L43_1.m_CutScenProcessKey = 0
L43_1.m_CutScenID = 7800102
L43_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Face = "UNIT_IDLE"
L43_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L43_1.m_Pos = "C"
L43_1.m_Talk_KOREA = "그건 사장님도, 저도, 그리고 당신도 마찬가지죠."
L43_1.m_fTalkTime = 0.03
L43_1.m_Talk_JPN = "それは社長も、私も、あなたも同じ。"
L43_1.m_Talk_ENG = "That is true for Boss, for me, and for you."
L43_1.m_Talk_TWN = "這點不只是老闆，我，還有你都一樣。"
L43_1.m_Talk_DEU = "That is true for Boss, for me, and for you."
L43_1.m_Talk_FRA = "That is true for Boss, for me, and for you."
L44_1 = {}
L44_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@29#Talk"
L44_1.m_CutScenProcessKey = 0
L44_1.m_CutScenID = 7800102
L44_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_PRIDE"
L44_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L44_1.m_Pos = "C"
L44_1.m_Talk_KOREA = "인간이기 위해서, 이름과 겉모습 같은 건 중요하지 않다고 생각해요."
L44_1.m_fTalkTime = 0.03
L44_1.m_Talk_JPN = "人間であるために、名前や見た目は関係ないと思います。"
L44_1.m_Talk_ENG = "To be human, names and outer forms don't matter."
L44_1.m_Talk_TWN = "為了做個真正的人類，我認為名字和外表這些並不重要。"
L44_1.m_Talk_DEU = "To be human, names and outer forms don't matter."
L44_1.m_Talk_FRA = "To be human, names and outer forms don't matter."
L45_1 = {}
L45_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@30#Talk"
L45_1.m_CutScenProcessKey = 0
L45_1.m_CutScenID = 7800102
