L45_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L45_1.m_Pos = "C"
L45_1.m_Talk_KOREA = "중요한 건… 그래요, <color=#ffd34c>마음</color>이죠."
L45_1.m_fTalkTime = 0.03
L45_1.m_Talk_JPN = "大事なのは……そう、<color=#ffd34c>心</color>です。"
L45_1.m_Talk_ENG = "What matters is... Yes, the <color=#ffd34c>heart</color>."
L45_1.m_Talk_TWN = "重要的是……沒錯，是<color=#ffd34c>心</color>。"
L45_1.m_Talk_DEU = "What matters is... Yes, the <color=#ffd34c>heart</color>."
L45_1.m_Talk_FRA = "What matters is... Yes, the <color=#ffd34c>heart</color>."
