L49_1 = {}
L49_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@32#Talk"
L49_1.m_CutScenProcessKey = 0
L49_1.m_CutScenID = 7800102
L49_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_Face = "UNIT_PRIDE"
L49_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L49_1.m_Pos = "C"
L49_1.m_Talk_KOREA = "실패에 굴하지 않고, <color=#ffd34c>더 나은 세상을 위해</color> 스스로 나아가려는 의지."
L49_1.m_fTalkTime = 0.03
L49_1.m_Talk_JPN = "失敗しても屈せず、<color=#ffd34c>より良い世界のために</color>前へ進もうとする意志。"
L49_1.m_Talk_ENG = "The will to keep moving forward <color=#ffd34c>for a better world</color> without bowing to failure."
L49_1.m_Talk_TWN = "不因失敗屈服，為了<color=#ffd34c>更好的未來</color>勇於前進的意志。"
L49_1.m_Talk_DEU = "The will to keep moving forward <color=#ffd34c>for a better world</color> without bowing to failure."
