L4_1 = {}
L4_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@35#Talk"
L4_1.m_CutScenProcessKey = 0
L4_1.m_CutScenID = 7800102
L4_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_IDLE"
L4_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L4_1.m_Pos = "C"
L4_1.m_Talk_KOREA = "과거, 당신이 어떤 실수를 저질렀고, 어째서 그런 모습이 되었는지는 모르겠지만."
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "過去にあなたがどんな間違いを犯したのか、なぜそのような姿になったのかは分かりませんが。"
L4_1.m_Talk_ENG = "I do not know what mistake you made in the past, or why you became like this."
L4_1.m_Talk_TWN = "雖然我不清楚過去你犯了什麼錯、為什麼會變成那副模樣。"
L4_1.m_Talk_DEU = "I do not know what mistake you made in the past, or why you became like this."
L4_1.m_Talk_FRA = "I do not know what mistake you made in the past, or why you became like this."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@36#Talk"
L5_1.m_CutScenProcessKey = 0
L5_1.m_CutScenID = 7800102
L5_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_SERIOUS"
L5_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L5_1.m_Pos = "C"
L5_1.m_Talk_KOREA = "과거의 약점을 극복하고, 진화를 멈추지 않으려는 그 알고리즘이야 말로……."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "過去の弱点を乗り越え、進化し続けようとするそのアルゴリズムこそ……"
L5_1.m_Talk_ENG = "But that algorithm which strives to overcome past weakness and never cease evolving..."
L5_1.m_Talk_TWN = "但克服過去的弱點、持續進化的演算法……"
L5_1.m_Talk_DEU = "But that algorithm which strives to overcome past weakness and never cease evolving..."
L5_1.m_Talk_FRA = "But that algorithm which strives to overcome past weakness and never cease evolving..."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "OMEN_LOTUS_INTERUDE1@37#Talk"
L6_1.m_CutScenProcessKey = 0
L6_1.m_CutScenID = 7800102
L6_1.m_CutScenStrID = "OMEN_LOTUS_INTERUDE1"
L6_1.m_bWaitClick = true
