L6_1.m_Face = "UNIT_SERIOUS"
L6_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L6_1.m_Pos = "C"
L6_1.m_Talk_KOREA = "당신을 한층 더 인간답게 만들어주는 마음이라고 할 수 있지 않을까요?"
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "あなたをより一層人間らしくする心だと言えるんじゃないでしょうか？"
L6_1.m_Talk_ENG = "Couldn't that be the heart that makes you more human?"
L6_1.m_Talk_TWN = "才是讓你更像人類的心吧？"
L6_1.m_Talk_DEU = "Couldn't that be the heart that makes you more human?"
L6_1.m_Talk_FRA = "Couldn't that be the heart that makes you more human?"
